import sys

MOD = 1_000_000_007

def mat_mul(A, B):
    return [
        [(A[0][0]*B[0][0] + A[0][1]*B[1][0]) % MOD, (A[0][0]*B[0][1] + A[0][1]*B[1][1]) % MOD],
        [(A[1][0]*B[0][0] + A[1][1]*B[1][0]) % MOD, (A[1][0]*B[0][1] + A[1][1]*B[1][1]) % MOD],
    ]

def fib(n: int) -> int:
    if n <= 0:
        return 0
    res = [[1, 0], [0, 1]]
    base = [[1, 1], [1, 0]]
    while n > 0:
        if n % 2 == 1:
            res = mat_mul(res, base)
        base = mat_mul(base, base)
        n //= 2
    return res[0][1]

if __name__ == "__main__":
    print(fib(int(sys.argv[1])))

